        def end_poll(seconds):
            raise EndFirstPoll()

        monkeypatch.setattr(watch.subprocess, "run", fake_run)
        monkeypatch.setattr(watch.subprocess, "Popen", fake_launch)
        monkeypatch.setattr(watch.time, "sleep", end_poll)
